mapper.sql:

	WHERE EDR.업체코드 = #{bcncCode}



		AND (
			UPPER(RTRIM(EDR.업체코드)) LIKE UPPER('%'+#{searchData1}+'%') 
			OR UPPER(RTRIM(CM.상호)) LIKE UPPER('%'+#{searchData1}+'%') 
			OR UPPER(RTRIM(EDR.착지업체)) LIKE UPPER('%'+#{searchData1}+'%') 
		)



AND EDR.출고사업장 = #{registBplc}

mapper.update:

UPDATE  웹거래처 SET
	LOGIN_PW = EncryptByPassPhrase('SGISERPW', CONVERT(VARCHAR(MAX), #{password}))
	, 수정자 = #{bcncCode}
	, 수정일자 = CONVERT(VARCHAR,GETDATE(),112)
	, 수정시간 = REPLACE(CONVERT(VARCHAR,GETDATE(),108),':','')
WHERE 
	1=1
	AND RTRIM(거래처코드) = #{bcncCode}
	AND RTRIM(LOGIN_ID) = #{loginId}
